public static double calculateAverageBalance(List<Double> closingBalances) {
    if (closingBalances == null || closingBalances.isEmpty()) {
        throw new IllegalArgumentException("The list of closing balances must not be null or empty.");
    }

    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            throw new IllegalArgumentException("Balances cannot contain null values.");
        }
        sum += balance;
    }

    return sum / closingBalances.size();
}

