public static String convertDatesToWeekdays(String date) {
    if (date == null || date.isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
    java.time.LocalDate parsedDate;
    try {
        parsedDate = java.time.LocalDate.parse(date, formatter);
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format: " + date, e);
    }

    java.time.format.TextStyle fullStyle = java.time.format.TextStyle.FULL;
    String weekday = parsedDate.getDayOfWeek().getDisplayName(fullStyle, java.util.Locale.ENGLISH);
    String monthName = parsedDate.getMonth().getDisplayName(fullStyle, java.util.Locale.ENGLISH);

    int month = parsedDate.getMonthValue();
    int day = parsedDate.getDayOfMonth();
    int year = parsedDate.getYear();

    return monthName + " " + day + ", " + year + " is a " + weekday;
}

