public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20;
    if (k == 0) {
        long sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return (double) sum / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return (double) sum / (n - 2 * k);
}

