public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    // Handle edge cases
    if (low > high) {
        return result;
    }
    // Check single-digit numbers (0-9)
    for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
        result.add(i);
    }
    // Use BFS to generate stepping numbers with 2 or more digits
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.add(i);
    }
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            continue;
        }
        // If current is within the range, add it
        if (current >= low) {
            result.add(current);
        }
        // Generate next possible stepping numbers
        int lastDigit = current % 10;
        int next1 = current * 10 + (lastDigit - 1);
        int next2 = current * 10 + (lastDigit + 1);
        if (next1 <= high && lastDigit > 0) {
            queue.add(next1);
        }
        if (next2 <= high && lastDigit < 9) {
            queue.add(next2);
        }
    }
    // Sort the result to ensure ascending order
    Collections.sort(result);
    return result;
}

