public static int countDigitOne(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }

    int count = 0;
    long base = 1;

    while (base <= n) {
        long higher = n / (base * 10);
        int current = (int) ((n / base) % 10);
        int lower = (int) (n % base);

        if (current < 1) {
            count += higher * base;
        } else if (current == 1) {
            count += higher * base + lower + 1;
        } else {
            count += (higher + 1) * base;
        }

        base *= 10;
    }

    return count;
}

