public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    String s = String.valueOf(n);
    char[] chars = s.toCharArray();

    // Find the rightmost digit that is smaller than some digit to its right
    int i = chars.length - 2;
    while (i >= 0 && chars[i] >= chars[i + 1]) {
        i--;
    }

    if (i < 0) {
        // The number is in descending order, no larger permutation exists
        return -1;
    }

    // Find the rightmost digit that is greater than chars[i]
    int j = chars.length - 1;
    while (j > i && chars[j] <= chars[i]) {
        j--;
    }

    // Swap chars[i] and chars[j]
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = chars.length - 1;
    while (left < right) {
        char t = chars[left];
        chars[left] = chars[right];
        chars[right] = t;
        left++;
        right--;
    }

    // Check for leading zeros (shouldn't happen for positive integer with first digit non-zero, but just in case)
    if (chars[0] == '0') {
        return -1;
    }

    try {
        return Integer.parseInt(new String(chars));
    } catch (NumberFormatException e) {
        return -1;
    }
}

