public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    while (result.size() < n) {
        result.add(current);
        if (current * 10 <= n) {
            current = current * 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current = current / 10;
            }
            current++;
        }
    }
    return result;
}

