public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;

    // Precompute perfect squares up to n
    java.util.List<Integer> squares = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
    }

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        // Check if i itself is a perfect square
        if (i * i == i) { // this is not the right way, better to check via squares list or Math
            dp[i] = 1;
        }
        for (int sq : squares) {
            if (sq > i) break;
            if (dp[i - sq] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - sq] + 1);
            }
        }
        // Also check if i is a perfect square directly
        int root = (int) Math.round(Math.sqrt(i));
        if (root * root == i) {
            dp[i] = 1;
        }
    }

    return dp[n];
}

